class PublishedMapRepository @Inject constructor(private val api:AraiapApi,private val dao:PublishedMapDao,@ApplicationContext private val c:Context){
 suspend fun cached(id:String)=dao.load(id)
 suspend fun refresh(id:String):NetworkResult<CachedMap>=when(val r=apiCall{api.publishedMap(id)}){is NetworkResult.Failure->r;is NetworkResult.Success->{val old=dao.load(id);if(old!=null&&old.map.version>=r.value.version)NetworkResult.Success(old)else try{val f=withContext(Dispatchers.IO){require(r.value.imageUrl.startsWith("http://")||r.value.imageUrl.startsWith("https://"));File(c.filesDir,"maps/$id/${r.value.version}/plan").also{it.parentFile?.mkdirs();URL(r.value.imageUrl).openStream().use{a->it.outputStream().use{b->a.copyTo(b)}}}};val at=System.currentTimeMillis();dao.replace(r.value,f.absolutePath,at);NetworkResult.Success(CachedMap(r.value,f.absolutePath,at))}catch(e:Exception){NetworkResult.Failure(null,e.message?:"Download failed.")}}}
}
data class NavigationScreenState(val venueId:String="",val map:FloorMap?=null,val imagePath:String?=null,val phase:NavigationPhase=NavigationPhase.MAP_ONLY,val start:StartPose?=null,val yaw:Float=0f,val destination:Destination?=null,val route:List<Point2D> = emptyList(),val remaining:Double=0.0,val accessible:Boolean=false,val explain:Boolean=false,val loading:Boolean=false,val notice:String?=null,val error:String?=null)
sealed interface NavigationAction{data class Open(val id:String):NavigationAction;data object Refresh:NavigationAction;data object SetPosition:NavigationAction;data class Pin(val p:Point2D):NavigationAction;data class Yaw(val v:Float):NavigationAction;data class Destination(val v:com.araiap.core.model.Destination):NavigationAction;data class Accessible(val v:Boolean):NavigationAction;data object Preview:NavigationAction;data object ExplainAr:NavigationAction;data class ArReady(val v:Boolean,val notice:String?=null):NavigationAction;data class Tracking(val t:CameraTracking,val p:Point2D?,val now:Long):NavigationAction;data object Recover:NavigationAction;data object CloseAr:NavigationAction}
@HiltViewModel class NavigationViewModel @Inject constructor(private val repo:PublishedMapRepository):ViewModel(){private val tracker=TrackingStateMachine();var state by mutableStateOf(NavigationScreenState());private set
 fun dispatch(a:NavigationAction){when(a){is NavigationAction.Open->open(a.id);NavigationAction.Refresh->refresh();NavigationAction.SetPosition->{tracker.beginSettingPosition();state=state.copy(phase=NavigationPhase.SETTING_POSITION,route=emptyList())};is NavigationAction.Pin->{val m=state.map?:return;if(isWalkable(m,a.p))state=state.copy(start=StartPose(a.p.x,a.p.y,state.yaw.toDouble()),error=null)else state=state.copy(error="Move the pin onto a corridor")};is NavigationAction.Yaw->state=state.copy(yaw=a.v,start=state.start?.copy(yawRadians=a.v.toDouble()));is NavigationAction.Destination->state=state.copy(destination=a.v);is NavigationAction.Accessible->state=state.copy(accessible=a.v);NavigationAction.Preview->preview();NavigationAction.ExplainAr->state=state.copy(explain=true);is NavigationAction.ArReady->{state=state.copy(explain=false,phase=if(a.v)NavigationPhase.NAVIGATING else NavigationPhase.MAP_ONLY,notice=a.notice);if(a.v)tracker.startAr()else tracker.mapOnly()};is NavigationAction.Tracking->track(a);NavigationAction.Recover->{tracker.recover();state=state.copy(phase=NavigationPhase.SETTING_POSITION,route=emptyList())};NavigationAction.CloseAr->{tracker.mapOnly();state=state.copy(phase=NavigationPhase.MAP_ONLY,notice="AR closed. Set position again before resuming.")}}}
 private fun open(id:String){state=NavigationScreenState(venueId=id,loading=true);viewModelScope.launch{repo.cached(id)?.let{apply(it)}?:refresh()}}
 private fun refresh(){if(state.route.isNotEmpty()){state=state.copy(error="Finish navigation before refreshing.");return};viewModelScope.launch{when(val r=repo.refresh(state.venueId)){is NetworkResult.Success->apply(r.value);is NetworkResult.Failure->{val c=repo.cached(state.venueId);if(c!=null)apply(c,"Offline cached map.")else state=state.copy(loading=false,error=r.message)}}}}
 private fun apply(c:CachedMap,n:String?=null){tracker.beginSettingPosition();state=state.copy(map=c.map,imagePath=c.imagePath,phase=NavigationPhase.SETTING_POSITION,loading=false,notice=n)}
 private fun preview(){val m=state.map?:return;val s=state.start?:return;val d=state.destination?:return;when(val r=findRoute(m,s.point,d.id,state.accessible)){is RouteResult.Found->{val n=m.routeNodes.associateBy{it.id};tracker.routeReady();state=state.copy(phase=NavigationPhase.ROUTE_PREVIEW,route=listOf(s.point)+r.nodeIds.mapNotNull{n[it]?.point},remaining=r.distanceMeters,error=null)}RouteResult.StartOffGraph->state=state.copy(error="Move the pin onto a corridor");RouteResult.DestinationMissing->state=state.copy(error="Destination missing.");RouteResult.Unreachable->state=state.copy(error="The destination cannot be reached.")}}
 private fun track(a:NavigationAction.Tracking){val m=state.map?:return;val d=state.destination?:return;val p=m.routeNodes.firstOrNull{it.id==d.nodeId}?.point?:return;tracker.update(a.t,a.now,a.p,p);state=state.copy(phase=tracker.snapshot.phase,start=tracker.snapshot.lastGoodPosition?.let{StartPose(it.x,it.y,state.start?.yawRadians?:0.0)}?:state.start,remaining=tracker.snapshot.lastGoodPosition?.distanceTo(p)?:state.remaining)}
}
private fun launchAr(c:Context,send:(NavigationAction)->Unit){val a=ArSessionController(c);when(a.availability()){ArAvailability.READY->send(NavigationAction.ArReady(true));ArAvailability.NEEDS_INSTALL->{val act=c as? Activity;if(act==null)send(NavigationAction.ArReady(false,"ARCore install unavailable."))else runCatching{a.requestInstall(act)}.onSuccess{send(NavigationAction.ArReady(it==com.google.ar.core.ArCoreApk.InstallStatus.INSTALLED,"Install ARCore then retry."))}.onFailure{send(NavigationAction.ArReady(false,"ARCore installation failed."))}}ArAvailability.UNAVAILABLE->send(NavigationAction.ArReady(false,"AR unavailable. 2D route remains usable."))};a.close()}
@Composable fun VisitorNavigationScreen(venueId:String,vm:NavigationViewModel=hiltViewModel()){val c=LocalContext.current;val permission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){if(it)launchAr(c,vm::dispatch)else vm.dispatch(NavigationAction.ArReady(false,"Camera denied. 2D route remains usable."))};LaunchedEffect(venueId){vm.dispatch(NavigationAction.Open(venueId))};val s=vm.state
 if(s.explain){Card(Modifier.padding(24.dp)){Column(Modifier.padding(20.dp)){Text("The camera shows arrows over the corridor. Video is never recorded or uploaded.");Button({permission.launch(Manifest.permission.CAMERA)}){Text("Continue")};TextButton({vm.dispatch(NavigationAction.ArReady(false,"Staying on 2D map."))}){Text("Stay on map")}}};return}
 if(s.phase==NavigationPhase.NAVIGATING){ArView(s,vm::dispatch);return}
 Column(Modifier.fillMaxSize().padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Indoor navigation",style=MaterialTheme.typography.headlineMedium);s.map?.let{m->Text("Map version ${m.version}");FloorMapCanvas(m,s.route,s.start,Modifier.fillMaxWidth().height(350.dp),s.imagePath){if(s.phase==NavigationPhase.SETTING_POSITION)vm.dispatch(NavigationAction.Pin(it))};when(s.phase){NavigationPhase.SETTING_POSITION->{Text("Tap your position and set facing.");Slider(s.yaw,{vm.dispatch(NavigationAction.Yaw(it))},valueRange=(-Math.PI).toFloat()..Math.PI.toFloat());LazyColumn(Modifier.height(130.dp)){items(m.destinations,key={it.id}){d->TextButton({vm.dispatch(NavigationAction.Destination(d))}){Text(d.name)}}};Row(verticalAlignment=Alignment.CenterVertically){Checkbox(s.accessible,{vm.dispatch(NavigationAction.Accessible(it))});Text("Accessible route")};Button({vm.dispatch(NavigationAction.Preview)},enabled=s.start!=null&&s.destination!=null){Text("Preview route")}}NavigationPhase.ROUTE_PREVIEW->{Text("${s.remaining.toInt()} m");Button({if(ContextCompat.checkSelfPermission(c,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)launchAr(c,vm::dispatch)else vm.dispatch(NavigationAction.ExplainAr)}){Text("Start AR")};Button({vm.dispatch(NavigationAction.SetPosition)}){Text("Set position again")}}NavigationPhase.TRACKING_LOST->{Text("Tracking lost.");Button({vm.dispatch(NavigationAction.Recover)}){Text("Set position again")}}NavigationPhase.ARRIVED->Text("You have arrived.");else->Button({vm.dispatch(NavigationAction.SetPosition)}){Text("Set position")}}};s.notice?.let{Text(it)};s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};TextButton({vm.dispatch(NavigationAction.Refresh)}){Text("Refresh map")}}}
@Composable private fun ArView(s:NavigationScreenState,send:(NavigationAction)->Unit){val c=LocalContext.current;val ar=remember{ArSessionController(c)};var t by remember{mutableStateOf<FloorSessionTransform?>(null)};DisposableEffect(Unit){runCatching{ar.resume()}.onFailure{send(NavigationAction.ArReady(false,"Unable to start AR."))};onDispose{ar.pause();ar.close()}};LaunchedEffect(Unit){while(isActive){ar.update()?.let{f->val start=s.start;if(start!=null&&t==null&&f.tracking==CameraTracking.TRACKING)t=FloorSessionTransform.atConfirmation(start,f.sessionCamera,0.0,0.0);send(NavigationAction.Tracking(f.tracking,t?.cameraFloorPosition(f.sessionCamera),System.currentTimeMillis()))};delay(16)}};Box(Modifier.fillMaxSize()){Text("AR navigation - ${s.remaining.toInt()} m",Modifier.align(Alignment.TopCenter).padding(24.dp));s.map?.let{FloorMapCanvas(it,s.route,s.start,Modifier.align(Alignment.BottomEnd).padding(12.dp).fillMaxWidth(.4f).height(180.dp),s.imagePath)};Button({send(NavigationAction.CloseAr)},Modifier.align(Alignment.BottomStart).padding(16.dp)){Text("Close AR")}}}
